parameterdescription.para:
証明書の生成に使用されるECCキーを含むECCKEY構造体へのポインタ Example CertmyCert;
wc_InitCert(&myCert);
WC_RNGrng;
//initializerng;
RsaKeykey;
//initializekey;
byte*derCert=malloc(FOURK_BUF);
word32certSz;
certSz=wc_MakeCert(&myCert,derCert,FOURK_BUF,&key,NULL,&rng);

証明書要求を生成するために使用されるRSAキーを含むRSAKEY構造体へのポインタ Example CertmyCert;
//initializemyCert
EccKeykey;
//initializekey;
byte*derCert=(byte*)malloc(FOURK_BUF);

word32certSz;
certSz=wc_MakeCertReq(&myCert,derCert,FOURK_BUF,NULL,&key);

証明書に署名するために使用されるECCキーを含むECCKey構造体へのポインタ Example CertmyCert;
byte*derCert=(byte*)malloc(FOURK_BUF);
//initializemyCert,derCert
RsaKeykey;
//initializekey;
WC_RNGrng;
//initializerng

word32certSz;
certSz=wc_SignCert(myCert.bodySz,myCert.sigType,derCert,FOURK_BUF,
&key,NULL,
&rng);

証明書に署名するために使用されるRSAキーを含むRSAKEY構造体へのポインタ Example CertmyCert;
byte*derCert=(byte*)malloc(FOURK_BUF);
//initializemyCert,derCert
RsaKeykey;
//initializekey;
WC_RNGrng;
//initializerng

word32certSz;
certSz=wc_MakeSelfCert(&myCert,derCert,FOURK_BUF,&key,NULL,&rng);
